window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[87]={"id":"087","numero":87,"titre":"Épistaxis","objectifs":[{"id":"87-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une épistaxis","contenu":"<p>L'<strong>épistaxis</strong> désigne un <span class=\"kw-def\">écoulement sanglant provenant des cavités nasales</span>. C'est un motif de consultation très fréquent, le plus souvent <span class=\"kw-clinique\">bénin</span>, mais qui peut devenir, par son <span class=\"kw-alerte\">abondance</span>, sa <span class=\"kw-alerte\">répétition</span> ou la <span class=\"kw-alerte\">fragilité du terrain</span>, une véritable <strong><span class=\"kw-alerte\">urgence</span> médicochirurgicale</strong>.</p>\n\n      <table >\n        <thead>\n          <tr><th>Cadre nosologique</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Épistaxis-maladie</strong></td>\n            <td><span class=\"kw-clinique\">Épistaxis essentielle du sujet jeune</span> due à des ectasies de la <strong>tache vasculaire</strong> située à la partie <strong>antéro-inférieure de la cloison nasale</strong> (plexus de Kiesselbach).</td>\n          </tr>\n          <tr>\n            <td><strong>Épistaxis-symptôme</strong></td>\n            <td>Signe révélateur ou complication de nombreuses affections (<span class=\"kw-def\">HTA</span>, troubles de l'hémostase, tumeurs nasosinusiennes, Rendu-Osler, traumatismes…).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Pivot anatomique.</strong> Deux territoires de saignement à distinguer dès la définition : <span class=\"kw-clinique\">épistaxis antérieure</span> (tache de Kiesselbach, le plus fréquent, accessible à l'examen) et <span class=\"kw-alerte\">épistaxis postérieure</span> (artère sphénopalatine, plus profonde, plus volontiers abondante).\n      </div>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/epistaxis","label":"Radiopaedia : Epistaxis"},{"href":"https://radiopaedia.org/articles/nose","label":"Radiopaedia : Nose (anatomie)"}]},{"id":"87-2","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les critères diagnostiques et de diagnostic différentiel","contenu":"<p>Le <span class=\"kw-def\">diagnostic positif</span> est <strong>clinique</strong>. Il repose sur la mise en évidence d'un écoulement sanglant extériorisé par <span class=\"kw-clinique\">les</span> narines (saignement antérieur) ou par les choanes (saignement postérieur), confirmé par l'examen ORL après évacuation des caillots.</p>\n\n      <table >\n        <thead>\n          <tr><th>Voie d'extériorisation</th><th>Présentation clinique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Saignement antérieur</strong></td>\n            <td><span class=\"kw-clinique\">Écoulement extériorisé par les narines</span> — le plus fréquent, le plus souvent unilatéral, accessible à la rhinoscopie antérieure.</td>\n          </tr>\n          <tr>\n            <td><strong>Saignement postérieur</strong></td>\n            <td><span class=\"kw-alerte\">Écoulement sanglant sur la paroi pharyngée postérieure</span> à l'examen pharyngé — extériorisation par <span class=\"kw-clinique\">les</span> choanes, plus difficile à contrôler.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><strong>Confirmation par l'examen ORL</strong> : rhinoscopie antérieure et examen pharyngé, réalisés après :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Évacuation des caillots par mouchage</span></li>\n        <li><span class=\"kw-clinique\">Méchage avec Xylocaïne à la naphazoline pendant 10 minutes</span> (anesthésie locale + vasoconstriction)</li>\n      </ul>\n\n      <table >\n        <thead>\n          <tr><th><span class=\"kw-def\">Diagnostic différentiel</span></th><th>Élément discriminant</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Hémoptysie</span></strong></td>\n            <td>Saignement extériorisé lors d'un <span class=\"kw-clinique\">effort de toux</span>, sang rouge spumeux d'origine bronchique.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Hématémèse</span></strong></td>\n            <td>Saignement extériorisé principalement par la bouche, lors d'un <span class=\"kw-clinique\">effort de vomissement</span>, sang digéré ± alimentaire.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Rupture</span> carotidienne</strong></td>\n            <td>Saignement d'origine pharyngée chez un patient avec <span class=\"kw-alerte\">ATCD d'irradiation cervicofaciale</span> — <span class=\"kw-alerte\">urgence</span> vitale absolue.</td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"87-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les données d’interrogatoire et d’examen clinique à rechercher devant une épistaxis","contenu":"<p>L'interrogatoire et l'examen clinique poursuivent trois objectifs simultanés : <strong>évaluer la gravité</strong>, <strong>orienter l'étiologie</strong>, et <strong>localiser le saignement</strong> pour guider le traitement.</p>\n\n      <table >\n        <thead>\n          <tr><th>Axe</th><th>Éléments à rechercher</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Terrain</span> (interrogatoire)</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-alerte\">Âge élevé</span>, insuffisance coronarienne, <span class=\"kw-def\">terrain</span> <span class=\"kw-alerte\">polyvasculaire</span></li>\n                <li><span class=\"kw-alerte\">Trouble de l'hémostase</span> constitutionnel ou <span class=\"kw-etio\">acquis</span> (<span class=\"kw-ttt\">AVK</span>, AAP, hémophilie, IH…)</li>\n                <li>Lésions nasales à risque <span class=\"kw-etio\">hémorragique</span> : <span class=\"kw-clinique\">Rendu-Osler</span>, <span class=\"kw-clinique\">tumeur nasale ou sinusienne</span></li>\n                <li><span class=\"kw-def\">HTA</span>, traumatisme récent, prise de cocaïne</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Gravité clinique</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-alerte\">Tachycardie</span>, <span class=\"kw-alerte\">hypotension artérielle</span></li>\n                <li><span class=\"kw-alerte\">Pâleur</span>, <span class=\"kw-clinique\">sueurs</span>, agitation</li>\n                <li>Puis <span class=\"kw-alerte\">marbrures</span>, <span class=\"kw-clinique\">cyanose</span>, troubles de conscience</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Abondance</strong></td>\n            <td>\n              <p>Souvent difficile à estimer : surévaluée par le patient/entourage, ou sous-évaluée si épistaxis déglutie. Critères évocateurs d'un saignement abondant 🚩 :</p>\n              <ul>\n                <li><span class=\"kw-alerte\">Bilatéralité</span></li>\n                <li><span class=\"kw-alerte\">Épistaxis antérieure ET postérieure</span></li>\n                <li><span class=\"kw-alerte\">Persistance depuis plusieurs jours</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Orientation étiologique</strong></td>\n            <td>Examen facial à la recherche de <span class=\"kw-clinique\">télangiectasies</span> orientant vers une maladie de Rendu-Osler. Saignement <strong>unilatéral</strong> → orientation locale ; saignement <strong>bilatéral</strong> → orientation générale.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Épistaxis bénigne <span class=\"kw-bio\">vs</span> grave.</strong> Bénigne : saignement antérieur unilatéral, goutte à goutte, tache de Kiesselbach, état général conservé. Grave : saignement bilatéral antéro-postérieur, abondant, retentissement hémodynamique (PA basse, <span class=\"kw-clinique\">pâleur</span>, <span class=\"kw-clinique\">sueurs</span>), co-morbidités à risque (coronaropathie, sténose carotidienne), troubles de la coagulation / <span class=\"kw-ttt\">AVK</span>.\n      </div>","frequence":3},{"id":"87-4","rang":"A","rubrique":"Examens complémentaires","titre":"Descrire les examens biologiques de base dans une épistaxis","contenu":"<p>La biologie n'est <strong>pas systématique</strong>. Son indication est guidée par la présence de <span class=\"kw-alerte\">signes de gravité</span> ou par le contexte étiologique.</p>\n\n      <table >\n        <thead>\n          <tr><th>Situation</th><th>Examens biologiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Absence de <span class=\"kw-alerte\">signe de gravité</span></strong></td>\n            <td><span class=\"kw-clinique\">Aucun examen complémentaire nécessaire</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Critère(s) de gravité</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">NFS</span> (Hb, <span class=\"kw-bio\">plaquettes</span>)</li>\n                <li><span class=\"kw-clinique\">Bilan d'hémostase</span> (<span class=\"kw-bio\">TP</span>, <span class=\"kw-bio\">TCA</span>, <span class=\"kw-bio\">fibrinogène</span>)</li>\n                <li><span class=\"kw-clinique\">Bilan pré-transfusionnel</span> : groupe ABO, Rhésus, RAI</li>\n                <li><span class=\"kw-clinique\">Créatininémie</span> (cochée vraie en annale)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Selon contexte</strong></td>\n            <td>\n              <ul>\n                <li>Études plus complètes de l'hémostase : temps de saignement, dosage des facteurs de la coagulation</li>\n                <li><span class=\"kw-clinique\">ECG, troponine</span> → recherche d'une souffrance myocardique</li>\n                <li><span class=\"kw-clinique\">Créatininémie</span> → si une artério-embolisation est envisagée (produit de contraste iodé)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>","frequence":2},{"id":"87-5","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l’indication des examens d’imagerie devant une épistaxis","contenu":"<p>L'imagerie n'est <strong>pas systématique</strong> dans l'épistaxis. Elle est indiquée dans deux situations principales : suspicion de <span class=\"kw-clinique\">lésion</span> vasculaire post-traumatique, et suspicion de tumeur nasosinusienne.</p>\n\n      <table >\n        <thead>\n          <tr><th>Indication</th><th>Examen</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Post-traumatique avec suspicion de <span class=\"kw-clinique\">lésion</span> de l'artère carotide interne</strong> (fracture transsphénoïdale)</td>\n            <td><span class=\"kw-clinique\">Angio-TDM cervicofaciale</span> — recherche d'une <span class=\"kw-alerte\">rupture</span> de la carotide interne dans le sinus sphénoïdal (épistaxis foudroyante) et d'une éventuelle <span class=\"kw-clinique\">fistule</span> carotido-caverneuse associée.</td>\n          </tr>\n          <tr>\n            <td><strong>Suspicion de tumeur nasale ou sinusienne</strong></td>\n            <td><span class=\"kw-clinique\">TDM du massif facial injectée</span>, complétée par <span class=\"kw-clinique\">IRM injectée</span> ensuite — <span class=\"kw-def\">bilan d'extension</span> d'un cancer du cavum, cancer de l'ethmoïde, ou tumeur bénigne (fibrome nasopharyngien).</td>\n          </tr>\n          <tr>\n            <td><strong>Fibrome nasopharyngien (cas particulier)</strong></td>\n            <td><span class=\"kw-clinique\">IRM + angiographie en pré-opératoire</span>. ⚠️ <span class=\"kw-alerte\">Biopsies contre-indiquées</span> (tumeur très vascularisée, risque <span class=\"kw-etio\">hémorragique</span>).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Signes d'alerte cliniques orientant l'imagerie.</strong> Épistaxis qui s'éclaircit → évoquer une <span class=\"kw-alerte\">fracture de l'étage antérieur de la base du crâne</span> (rhinoliquorrhée). Épistaxis + <span class=\"kw-alerte\">exophtalmie pulsatile</span> → évoquer une <span class=\"kw-alerte\">fistule carotido-caverneuse</span> (gravissime).\n      </div>","frequence":1},{"id":"87-6","rang":"B","rubrique":"Prise en charge","titre":"Connaître le principe de traitement par radiologie interventionnelle de l’épistaxis","contenu":"<p>La radiologie interventionnelle correspond à l'<strong>embolisation artérielle</strong>, indiquée après échec du tamponnement antéropostérieur avec récidive importante de l'épistaxis.</p>\n\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Cible</strong></td>\n            <td>Branches de l'<span class=\"kw-clinique\">artère carotide externe</span> :\n              <ul>\n                <li><span class=\"kw-clinique\">Artère sphénopalatine</span></li>\n                <li><span class=\"kw-clinique\">Artère de la sous-cloison</span> (branche de l'artère faciale)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Modalités</strong></td>\n            <td>Voie endovasculaire, sous <span class=\"kw-clinique\">anesthésie locale</span> ou sous <span class=\"kw-clinique\">anesthésie générale</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Situation à privilégier</strong></td>\n            <td><span class=\"kw-clinique\">Trouble de l'hémostase</span> constitutionnel ou traitement <span class=\"kw-ttt\">antiagrégant</span>/<span class=\"kw-ttt\">anticoagulant</span> ne pouvant pas être interrompu.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ci\">Contre-indication</span> absolue</strong> ⚠️</td>\n            <td><span class=\"kw-alerte\">PAS d'embolisation des artères ethmoïdales</span> → risque d'<span class=\"kw-alerte\">hémiplégie</span> ou de <span class=\"kw-alerte\">cécité</span> (<span class=\"kw-clinique\">les</span> ethmoïdales sont des branches de l'ophtalmique, issue de la carotide interne).</td>\n          </tr>\n          <tr>\n            <td><strong>Alternative chirurgicale</strong></td>\n            <td><span class=\"kw-clinique\">Ligature de l'artère sphénopalatine</span> (<span class=\"kw-ttt\">chirurgie</span>) ; en dernier recours : <span class=\"kw-clinique\">ligature de l'artère ethmoïdale antérieure</span> (rare).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Cas particuliers nécessitant la radiologie interventionnelle.</strong> Angiomatose de Rendu-Osler, épistaxis post-traumatique, tumeurs rhinosinusiennes, malformation artérioveineuse, saignement postopératoire.\n      </div>","frequence":0},{"id":"87-7","rang":"A","rubrique":"Prise en charge","titre":"Connaître la stratégie thérapeutique dans une épistaxis","contenu":"<p>La prise en charge associe des <strong>mesures générales</strong> et un <strong>contrôle progressif du saignement</strong>, par paliers d'efficacité croissante (arbre décisionnel canonique).</p>\n\n      <table >\n        <thead>\n          <tr><th>Mesure</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Orientation</strong></td>\n            <td>\n              Hospitaliser <span class=\"kw-clinique\">les</span> patients <span class=\"kw-alerte\">avec critères de gravité 🏥</span> (notamment insuffisance coronarienne), qui :\n              <ul>\n                <li>Nécessitent transfusion ou pose d'une sonde à double ballonnet ou tout autre geste hémostatique invasif</li>\n                <li>Présentent des difficultés de <span class=\"kw-def\">surveillance</span> à domicile (âge, <span class=\"kw-def\">isolement</span>, précarité)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Mesures générales</strong></td>\n            <td>\n              <ul>\n                <li>Patient en <span class=\"kw-clinique\">position assise ou demi-assise</span> (risque d'inhalation en position allongée)</li>\n                <li>Anxiolytique oral ou injectable si patient agité/anxieux</li>\n                <li><span class=\"kw-clinique\">Transfusion CGR</span> : si Hb &lt;<span class=\"kw-chiffre\"> 7 g/dL</span>, ou &lt;<span class=\"kw-chiffre\"> 10 g/dL</span> si insuffisance coronarienne aiguë</li>\n                <li><span class=\"kw-clinique\">Transfusion de plaquettes</span> : si <span class=\"kw-alerte\">choc</span> <span class=\"kw-etio\">hémorragique</span> avec <span class=\"kw-bio\">plaquettes</span> &lt; <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>50</span> G/L</span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><strong>Premiers gestes</strong> (effectuables par le patient à domicile, à enseigner aux patients récidivants) :</p>\n      <ul>\n        <li>Sucer un glaçon</li>\n        <li>Évacuation des caillots par mouchage</li>\n        <li>Position <span class=\"kw-clinique\">tête surélevée et légèrement penchée en avant</span></li>\n        <li><span class=\"kw-clinique\">Compression bidigitale antérieure de 10 minutes</span> « montre en main »</li>\n        <li>Tampons hémostatiques locaux à la partie antérieure de la fosse nasale (possible par le patient lui-même)</li>\n      </ul>\n\n      <p><strong>Prise en charge médicale en cas d'échec</strong> — séquence canonique :</p>\n      <ol>\n        <li>Évacuation des caillots par mouchage</li>\n        <li><span class=\"kw-clinique\">Méchage</span> des cavités nasales avec cotons imbibés de <strong>Xylocaïne à la naphazoline</strong>, pendant <strong><span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>10</span> min</span>utes</strong> (anesthésie locale + rétraction muqueuse vasoconstrictrice)</li>\n        <li>Examen des cavités nasales pour <span class=\"kw-clinique\">localiser le saignement</span></li>\n        <li><span class=\"kw-clinique\">Hémostase élective à la pince coagulante</span> si zone accessible</li>\n        <li><span class=\"kw-clinique\">Tamponnement antérieur classique</span> : si échec, récidive, ou site non visualisé</li>\n        <li><span class=\"kw-clinique\">Tamponnement antéropostérieur</span> par sonde à double ballonnet : si échec, surtout si saignement postérieur</li>\n      </ol>\n\n      <div class=\"callout callout-info\">\n        <strong>Arbre décisionnel après échec du tamponnement antéropostérieur.</strong> Avis spécialisé urgent → <span class=\"kw-clinique\">ligature ou embolisation de la sphénopalatine</span> (privilégier l'embolisation si trouble de l'hémostase) → en dernier recours, <span class=\"kw-clinique\">ligature de l'artère ethmoïdale antérieure</span>. ⚠️ Jamais d'embolisation des artères ethmoïdales (risque <span class=\"kw-clinique\">hémiplégie</span> / cécité).\n      </div>\n\n      <p><strong>Cas particulier — épistaxis essentielle (tache de Kiesselbach).</strong> Pas de tamponnement sur un saignement de la tache de Kiesselbach. Traitement par <span class=\"kw-clinique\">compression</span> ± <span class=\"kw-clinique\">cautérisation</span> chimique ou électrique, idéalement à distance d'un épisode, sous anesthésie locale en consultation ORL.</p>\n\n      <p class=\"obj-renvois\"><em>📎 Renvois pédagogiques : voir obj-10 (tamponnement antérieur) · obj-11 (tamponnement antéropostérieur) · obj-5 (radiologie interventionnelle) · obj-7 (gestion <span class=\"kw-def\">HTA</span>).</em></p>","frequence":7},{"id":"87-8","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de la gestion thérapeutique de l’HTA au cours d’une épistaxis","contenu":"<p>L'<span class=\"kw-def\">HTA</span> est un facteur étiologique et aggravant majeur de l'épistaxis chez le sujet âgé. Sa prise en charge s'intègre dans la <strong>prévention des récidives</strong>.</p>\n\n      <table >\n        <thead>\n          <tr><th>Phase</th><th>Conduite à tenir</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Phase aiguë</strong></td>\n            <td>L'<span class=\"kw-def\">HTA</span> peut être <span class=\"kw-clinique\">cause</span> de l'épistaxis, ou <span class=\"kw-clinique\">aggraver une autre cause</span>. Contrôle tensionnel par <span class=\"kw-clinique\">les</span> moyens habituels, en intégrant l'effet anxiogène du saignement.</td>\n          </tr>\n          <tr>\n            <td><strong>Après contrôle du saignement</strong></td>\n            <td>Si <span class=\"kw-clinique\">HTA persistante après traitement de l'épistaxis</span> → <span class=\"kw-clinique\">avis spécialisé</span> doit être proposé pour discuter la mise en place d'un <strong>traitement de fond antihypertenseur</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>Prévention des récidives</strong></td>\n            <td>L'équilibre tensionnel au long cours est l'un des piliers de la prévention, au même titre que la prise en charge spécifique d'une <span class=\"kw-clinique\">coagulopathie</span> (revoir l'indication des antithrombotiques) ou la cautérisation d'une <span class=\"kw-clinique\">tache vasculaire</span> ectasique.</td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"87-9","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales étiologies des épistaxis","contenu":"<p><span class=\"kw-clinique\">Les</span> étiologies se distribuent en deux grands cadres : <strong>épistaxis d'origine locale</strong> (épistaxis-symptôme, plutôt <span class=\"kw-clinique\">unilatérale</span>) et <strong>épistaxis d'origine générale</strong> (épistaxis-épiphénomène, plutôt <span class=\"kw-clinique\">bilatérale</span>).</p>\n\n      <table >\n        <thead>\n          <tr><th>Cadre</th><th>Étiologies principales (rang A)</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Locale — Traumatique</strong> (le plus fréquent)</td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Corps étrangers</span> (typique chez l'enfant)</li>\n                <li><span class=\"kw-clinique\">Perforations septales</span></li>\n                <li>Traumatismes opératoires : <span class=\"kw-clinique\">intubation nasale</span>, <span class=\"kw-clinique\">chirurgie nasosinusienne</span></li>\n                <li>Traumatisme nasal avec ou sans fracture des os propres du nez</li>\n                <li>Fracture du tiers moyen de la face</li>\n                <li>Traumatisme crânien : branches ethmoïdales de la carotide interne ou <span class=\"kw-alerte\">rupture</span> de la carotide interne dans le sinus sphénoïdal (<span class=\"kw-alerte\">épistaxis foudroyante</span>)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Générale — <span class=\"kw-def\">HTA</span></strong></td>\n            <td>Peut être cause d'épistaxis ou aggraver une autre cause de saignement.</td>\n          </tr>\n          <tr>\n            <td><strong>Générale — Maladies hémorragiques</strong></td>\n            <td>\n              Perturbation de l'hémostase primaire (temps vasculo-plaquettaire allongé, TC normal) :\n              <ul>\n                <li><span class=\"kw-clinique\">Capillarites</span> : <span class=\"kw-def\">purpura rhumatoïde</span>, purpuras immunoallergiques et <span class=\"kw-etio\">infectieux</span> (typhoïde, scarlatine, fulminans)</li>\n                <li><span class=\"kw-clinique\">Thrombopénies</span></li>\n                <li><span class=\"kw-clinique\">Thrombopathies</span> : <span class=\"kw-ttt\">antiagrégants</span>, <span class=\"kw-ttt\">AINS</span>, Glanzmann, Willebrand, <span class=\"kw-ci\">insuffisance rénale</span>, hémopathie</li>\n                <li><span class=\"kw-clinique\">Troubles de la coagulation</span> : hémophilie (<span class=\"kw-etio\">congénitale</span>), <span class=\"kw-ttt\">anticoagulants</span>, acquis (<span class=\"kw-ci\">insuffisance hépatique</span>, <span class=\"kw-alerte\">CIVD</span>)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Épistaxis essentielle</strong></td>\n            <td>\n              <span class=\"kw-clinique\">Épistaxis-maladie</span> du sujet jeune par ectasie de la tache vasculaire de Kiesselbach. Facteurs favorisants :\n              <ul>\n                <li>Grattage, <span class=\"kw-etio\">exposition solaire</span>, phénomènes vasomoteurs</li>\n                <li>Facteurs endocriniens : puberté, prémenstruelle, <span class=\"kw-ci\">grossesse</span></li>\n                <li>Artériosclérose (chez le sujet plus âgé)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Latéralité : un indice d'orientation.</strong> Saignement <span class=\"kw-clinique\">unilatéral</span> → orientation locale (corps étranger chez l'enfant, tumeur unilatérale chez l'adulte, fibrome nasopharyngien chez le jeune garçon). Saignement <span class=\"kw-clinique\">bilatéral</span> → orientation générale (<span class=\"kw-def\">HTA</span>, troubles de l'hémostase, médicaments).\n      </div>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/juvenile-nasopharyngeal-angiofibroma","label":"Radiopaedia : Juvenile nasopharyngeal angiofibroma"}]},{"id":"87-10","rang":"B","rubrique":"Étiologies","titre":"Connaître les autres étiologies des épistaxis","contenu":"<p>À côté des étiologies rang A, deux groupes méritent un focus rang B : <span class=\"kw-clinique\">les</span> <strong>causes tumorales</strong> (bénignes et malignes) et les <strong>maladies vasculaires</strong> (au premier rang desquelles la maladie de Rendu-Osler).</p>\n\n      <table >\n        <thead>\n          <tr><th>Groupe</th><th>Étiologies</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Tumorales — bénignes</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Fibrome nasopharyngien</span> (cf. focus ci-dessous)</li>\n                <li>Angiome de la cloison</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Tumorales — malignes</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-alerte\">Cancers du cavum</span></li>\n                <li><span class=\"kw-alerte\">Cancers rhinosinusiens</span> (cancer de l'ethmoïde)</li>\n              </ul>\n              Signes associés évocateurs : obstruction nasale chronique, déficit de paires crâniennes, otite séreuse, exophtalmie.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Maladies vasculaires</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Maladie de Rendu-Osler</span> (cf. focus ci-dessous)</li>\n                <li><span class=\"kw-alerte\">Rupture d'anévrisme carotidien intracaverneux</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Autres</strong></td>\n            <td>\n              <ul>\n                <li>Rhinosinusites aiguës ou chroniques (rares)</li>\n                <li>Cocaïne</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Focus — Fibrome nasopharyngien.</strong> Tumeur bénigne rare du <span class=\"kw-clinique\">jeune garçon (&gt; 10 ans)</span>, très vascularisée, développée au niveau de la paroi latérale de l'orifice choanale. Manifestations <strong>unilatérales</strong> : obstruction nasale progressive, rhinorrhée, <strong>épistaxis à répétition</strong> de plus en plus abondantes. ⚠️ <span class=\"kw-alerte\">Biopsies contre-indiquées</span> (risque <span class=\"kw-etio\">hémorragique</span>). <span class=\"kw-def\">Diagnostic différentiel</span> : UCNT (<span class=\"kw-clinique\">carcinome</span> indifférencié de type nasopharyngé). Imagerie : <span class=\"kw-imagerie\">IRM</span> ± <span class=\"kw-imagerie\">angiographie</span> pré-opératoire. Traitement : artério-embolisation puis <span class=\"kw-ttt\">exérèse</span> chirurgicale <span class=\"kw-chiffre\">72 h</span> après ; <span class=\"kw-ttt\">radiothérapie</span> si inextirpable. Tamponnement <span class=\"kw-ci\">à éviter</span> sauf extrême <span class=\"kw-alerte\">urgence</span>.\n      </div>\n\n      <div class=\"callout callout-info\">\n        <strong>Focus — Maladie de Rendu-Osler (angiomatose <span class=\"kw-etio\">hémorragique</span> familiale).</strong> Transmission <span class=\"kw-clinique\">autosomique dominante</span> à expressivité variable, pénétrance quasi complète à<span class=\"kw-chiffre\"> 50 ans</span>. Dérégulation de l'angiogenèse → <span class=\"kw-clinique\">télangiectasies</span> + MAV.\n        <ul>\n          <li><strong><span class=\"kw-def\">Critères de</span> Curaçao (1997)</strong> : épistaxis spontanées récurrentes · <span class=\"kw-clinique\">télangiectasies</span> cutanéo-muqueuses (lèvres, doigts, langue, palais) · atteinte familiale au 1er degré · MAV viscérale (pulmonaire <span class=\"kw-chiffre\">30-50 %</span>, hépatique <span class=\"kw-chiffre\">30-80 %</span>, neurologique <span class=\"kw-chiffre\">8-25 %</span>)</li>\n          <li><strong>Risques</strong> : anémie chronique ferriprive, hémorragies digestives, complications des MAV (embolie paradoxale, <span class=\"kw-clinique\">abcès</span> cérébral, <span class=\"kw-def\">insuffisance cardiaque</span> à débit élevé)</li>\n          <li><strong>Précaution</strong> : méchage prudent pour éviter le traumatisme d'autres <span class=\"kw-clinique\">télangiectasies</span></li>\n        </ul>\n      </div>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/hereditary-haemorrhagic-telangiectasia","label":"Radiopaedia : Hereditary haemorrhagic telangiectasia (Rendu-Osler)"}]},{"id":"87-11","rang":"A","rubrique":"Prise en charge","titre":"Connaître le principe du tamponnement antérieur","contenu":"<p><strong>Principe.</strong> Le tamponnement antérieur consiste à <span class=\"kw-clinique\">comprimer les plaies</span> de la muqueuse nasale par une mèche tassée dans la fosse nasale.</p>\n\n      <table >\n        <thead>\n          <tr><th>Étape</th><th>Modalités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1. Préparation</strong></td>\n            <td>\n              <ol>\n                <li>Patient assis ou demi-assis, <span class=\"kw-clinique\">mouchage énergique</span> pour évacuer <span class=\"kw-clinique\">les</span> caillots</li>\n                <li>Lavage des cavités nasales au sérum physiologique froid si besoin</li>\n                <li>Application de cotons ou compresses non tissées imbibées de <span class=\"kw-clinique\">Xylocaïne 5 % + naphazoline</span> (sauf chez jeune enfant)</li>\n                <li><span class=\"kw-ttt\">Antalgique</span> et/ou sédatif léger avant méchage</li>\n              </ol>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>2. Réalisation du tamponnement</strong></td>\n            <td>\n              <ol>\n                <li>Introduction d'une mèche à l'aide d'une <span class=\"kw-clinique\">pince à bouts mousses sans griffe</span>, ou pince nasale coudée (pince de Politzer)</li>\n                <li>Mèche enfoncée jusqu'à la <strong>partie postérieure de la fosse nasale</strong> en évitant de la faire basculer dans le pharynx</li>\n                <li>Mèche <strong>tassée en accordéon d'arrière en avant jusqu'à la narine</strong>, en suivant le <span class=\"kw-clinique\">plan du plancher nasal</span></li>\n                <li>Contention de l'extrémité antérieure du tamponnement par un ruban adhésif sur l'orifice narinaire</li>\n              </ol>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <table >\n        <thead>\n          <tr><th>Type de mèche</th><th>Indications · ATB</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Mèche résorbable</strong></td>\n            <td>\n              Privilégiée si :\n              <ul>\n                <li>Trouble de l'hémostase</li>\n                <li>Maladie de Rendu-Osler</li>\n                <li>Risque de récidive <span class=\"kw-etio\">hémorragique</span> importante à l'ablation</li>\n              </ul>\n              → <span class=\"kw-clinique\">Antibioprophylaxie indiquée</span> : <strong><span class=\"kw-ttt\">amoxicilline-acide clavulanique</span></strong> en 1ʳᵉ intention, <span class=\"kw-ttt\">clarithromycine</span> si <span class=\"kw-ci\">allergie</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Mèche non résorbable</strong></td>\n            <td>\n              Autres situations : mèche grasse vaselinée, tampon, mèche d'alginate de calcium.\n              <ul>\n                <li>Retrait à <strong><span class=\"kw-chiffre\">24-48 h</span></strong> après correction des facteurs favorisants</li>\n                <li><span class=\"kw-clinique\">Antibioprophylaxie non nécessaire</span> (inutile si mèche/tampon laissée &lt;<span class=\"kw-chiffre\"> 48 h</span>)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>","frequence":1},{"id":"87-12","rang":"B","rubrique":"Prise en charge","titre":"Connaître le principe du tamponnement antéropostérieur","contenu":"<p>Le tamponnement antéropostérieur s'effectue à l'aide d'une <strong>sonde à double ballonnet hémostatique</strong>. Sa réalisation revient à un médecin spécialiste <span class=\"kw-clinique\">ORL</span>, mais le ballonnet hémostatique doit figurer dans la <strong>trousse d'<span class=\"kw-alerte\">urgence</span> de tout médecin</strong>.</p>\n\n      <table >\n        <thead>\n          <tr><th>Étape</th><th>Modalités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Objectif</strong></td>\n            <td>\n              <ol>\n                <li>Confiner le saignement en complétant le tamponnement antérieur par une <span class=\"kw-clinique\">obturation postérieure des choanes</span> (alternative historique : compresses tassées dans le nasopharynx introduites par voie endobuccale)</li>\n                <li>Le saignement est ainsi confiné dans <span class=\"kw-clinique\">les</span> fosses nasales par définition inextensibles</li>\n              </ol>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Préparation</strong></td>\n            <td>\n              <ol>\n                <li>Patient assis ou demi-assis, mouchage énergique pour évacuer <span class=\"kw-clinique\">les</span> caillots</li>\n                <li>Lavage des cavités nasales au sérum physiologique froid si besoin</li>\n                <li>Application de cotons imbibés de Xylocaïne <span class=\"kw-chiffre\">5 %</span> + naphazoline (sauf jeune enfant)</li>\n                <li><span class=\"kw-ttt\">Antalgique</span> et/ou sédatif léger avant introduction</li>\n              </ol>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Mise en place</strong></td>\n            <td>\n              <ol>\n                <li>Introduction de la sonde <strong>dégonflée</strong> en suivant le plan du plancher nasal dans la fosse nasale jusque dans le <span class=\"kw-clinique\">cavum</span></li>\n                <li><span class=\"kw-clinique\">Gonflement du ballonnet postérieur</span> dans le cavum à une pression juste suffisante pour le bloquer dans la <strong>choane</strong> (au sérum physiologique à la seringue)</li>\n                <li><span class=\"kw-clinique\">Gonflement du ballonnet antérieur</span> dans la fosse nasale pour isoler et comprimer la cavité nasale</li>\n              </ol>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Surveillance</span></strong></td>\n            <td>\n              <ol>\n                <li>Noter le <strong>volume injecté</strong> dans <span class=\"kw-clinique\">les</span> ballonnets et l'<strong>heure de pose</strong></li>\n                <li>Dégonfler le ballonnet si possible toutes <span class=\"kw-clinique\">les</span> <strong><span class=\"kw-chiffre\">6-8 h</span></strong> → limiter le risque de <span class=\"kw-alerte\">nécrose muqueuse</span></li>\n                <li>Rester attentif aux zones de <span class=\"kw-def\">contact</span> sonde-peau → éviter toute <span class=\"kw-alerte\">escarre narinaire</span></li>\n              </ol>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Durée</strong></td>\n            <td>\n              <ul>\n                <li>Sonde à ballonnets laissée en place au maximum <span class=\"kw-clinique\">≤ 72 h</span></li>\n                <li>Dégonfler progressivement <span class=\"kw-clinique\">les</span> ballonnets dès <strong><span class=\"kw-chiffre\">24-48 h</span></strong></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Si échec.</strong> Avis spécialisé urgent → l<span class=\"kw-chiffre\">iga</span>ture ou embolisation de l'artère sphénopalatine (cf. obj-5 — radiologie interventionnelle).\n      </div>","frequence":1}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré :</strong> épistaxis le plus souvent <span class=\"kw-clinique\">bénigne</span>, mais peut devenir une <span class=\"kw-alerte\">urgence médicochirurgicale</span> par son <span class=\"kw-alerte\">abondance</span>, sa <span class=\"kw-alerte\">répétition</span> ou la <span class=\"kw-alerte\">fragilité du terrain</span><br><strong>1er geste :</strong> <span class=\"kw-ttt\">compression bidigitale antérieure</span> de <span class=\"kw-chiffre\">10 minutes</span> « montre en main », patient <span class=\"kw-ttt\">assis tête penchée en avant</span> après <span class=\"kw-ttt\">mouchage</span> des caillots<br><strong>Forme foudroyante :</strong> <span class=\"kw-alerte\">épistaxis foudroyante</span> par <span class=\"kw-etio\">rupture de l'artère carotide interne dans le sinus sphénoïdal</span> (contexte <span class=\"kw-etio\">post-traumatique</span>)</p>","hospit":"<p><strong>Ambulatoire :</strong> <span class=\"kw-clinique\">épistaxis bénigne</span> sans retentissement — premiers gestes réalisables par le <span class=\"kw-ttt\">patient lui-même à domicile</span><br><strong><span class=\"kw-alerte\">Hospitalisation</span> :</strong> patients avec <span class=\"kw-alerte\">critères de gravité</span> (notamment <span class=\"kw-alerte\">insuffisance coronarienne</span>) nécessitant <span class=\"kw-ttt\">transfusion</span>, <span class=\"kw-ttt\">sonde à double ballonnet</span> ou geste hémostatique invasif<br><strong>Aussi hospit :</strong> <span class=\"kw-alerte\">difficultés de surveillance à domicile</span> (âge, <span class=\"kw-def\">isolement</span>, précarité)<br><strong>Avis ORL urgent :</strong> en cas d'<span class=\"kw-alerte\">échec du tamponnement antéropostérieur</span> avec récidive importante (l<span class=\"kw-chiffre\">iga</span>ture / embolisation)</p>","redflags":"<ul><li><span class=\"kw-alerte\">Saignement bilatéral antéro-postérieur</span> (origine postérieure)</li><li><span class=\"kw-alerte\">Hémorragie abondante</span>, persistant depuis plusieurs jours</li><li>Retentissement hémodynamique : <span class=\"kw-alerte\">PA basse</span>, <span class=\"kw-clinique\">pâleur</span>, <span class=\"kw-clinique\">sueurs</span>, <span class=\"kw-alerte\">tachycardie</span>, agitation, puis <span class=\"kw-alerte\">marbrures</span>, <span class=\"kw-alerte\">cyanose</span>, <span class=\"kw-alerte\">troubles de conscience</span></li><li><span class=\"kw-def\">Terrain</span> à risque : <span class=\"kw-alerte\">terrain polyvasculaire</span>, <span class=\"kw-alerte\">coronaropathie</span>, <span class=\"kw-alerte\">sténose carotidienne</span>, âge élevé</li><li><span class=\"kw-alerte\">Troubles de la coagulation</span> ou patient sous <span class=\"kw-ttt\">AVK</span></li><li><span class=\"kw-clinique\">Lésion</span> à risque <span class=\"kw-etio\">hémorragique</span> : <span class=\"kw-etio\">maladie de Rendu-Osler</span>, <span class=\"kw-etio\">tumeur nasale ou sinusienne</span></li><li><span class=\"kw-alerte\">Épistaxis qui s'éclaircit</span> → évoquer une <span class=\"kw-etio\">fracture de l'étage antérieur de la base du crâne</span> (rhinoliquorrhée)</li><li><span class=\"kw-alerte\">Épistaxis + exophtalmie pulsatile</span> → évoquer une <span class=\"kw-etio\">fistule carotido-caverneuse</span></li></ul>","principes":"<p>Escalade hémostatique <span class=\"kw-ttt\">en escalier</span> : on ne passe à l'étape suivante qu'en cas d'<span class=\"kw-alerte\">échec</span> ou de <span class=\"kw-alerte\">récidive</span>.</p><p><strong>Mesures générales</strong></p><ul><li>Patient en <span class=\"kw-ttt\">position assise ou demi-assise</span> (risque d'inhalation en décubitus)</li><li><span class=\"kw-ttt\">Anxiolytique</span> oral ou injectable si patient agité/anxieux</li><li><span class=\"kw-ttt\">Transfusion de CGR</span> si <span class=\"kw-chiffre\">Hb < 7 g/dL</span> (ou <span class=\"kw-chiffre\">< 10 g/L si insuffisance coronarienne aiguë</span>)</li><li><span class=\"kw-ttt\">Transfusion de plaquettes</span> si choc hémorragique avec <span class=\"kw-chiffre\">plaquettes < 50 G/L</span></li></ul><p><strong>Contrôle du saignement (escalade)</strong></p><p><span class=\"kw-ci\">Jamais d'embolisation des artères ethmoïdales</span> : risque d'<span class=\"kw-alerte\">hémiplégie</span> ou de <span class=\"kw-alerte\">cécité</span></p><ul><li>1. <span class=\"kw-ttt\">Compression bidigitale antérieure</span> <span class=\"kw-chiffre\">10 min</span> après mouchage des caillots</li><li>2. <span class=\"kw-ttt\">Méchage à la Xylocaïne naphazoline</span> pendant <span class=\"kw-chiffre\">10 min</span> (anesthésie locale + vasoconstriction), puis examen pour localiser le saignement</li><li>3. <span class=\"kw-ttt\">Hémostase élective à la pince coagulante</span> si zone de saignement accessible</li><li>4. <span class=\"kw-ttt\">Tamponnement antérieur</span> si échec / récidive / site non visualisé</li><li>5. <span class=\"kw-ttt\">Tamponnement antéropostérieur</span> par <span class=\"kw-ttt\">sonde à double ballonnet</span> si échec, surtout saignements postérieurs</li><li>6. Si échec : <span class=\"kw-ttt\">ligature de l'artère sphénopalatine</span> ou <span class=\"kw-ttt\">embolisation des branches de la carotide externe</span> (privilégiée si <span class=\"kw-alerte\">trouble de l'hémostase</span>)</li><li>7. Dernier recours : <span class=\"kw-ttt\">ligature de l'artère ethmoïdale antérieure</span> (rare)</li></ul><p><strong>Mèches & <span class=\"kw-ttt\">antibioprophylaxie</span></strong></p><ul><li><span class=\"kw-ttt\">Mèches non résorbables</span> (mèche grasse vaselinée, tampon, alginate de calcium) : retrait à <span class=\"kw-chiffre\">24-48h</span>, <span class=\"kw-ci\">pas d'antibioprophylaxie</span> si laissées <span class=\"kw-chiffre\">< 48h</span></li><li><span class=\"kw-ttt\">Mèches résorbables</span> + <span class=\"kw-ttt\">antibioprophylaxie</span> (<span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> en 1re intention, <span class=\"kw-ttt\">clarithromycine</span> si allergie) si <span class=\"kw-alerte\">trouble de l'hémostase</span>, <span class=\"kw-etio\">Rendu-Osler</span> ou risque de récidive hémorragique à l'ablation</li></ul><p><strong>Cas particuliers</strong></p><ul><li>Saignement de la <span class=\"kw-etio\">tache de Kiesselbach</span> : <span class=\"kw-ci\">pas de tamponnement</span> → <span class=\"kw-ttt\">compression ± cautérisation</span></li><li><span class=\"kw-etio\">Rendu-Osler</span> / <span class=\"kw-etio\">fibrome nasopharyngien</span> : méchage <span class=\"kw-ci\">à éviter</span> (risque de léser d'autres télangiectasies / aggraver l'hémorragie), <span class=\"kw-ttt\">embolisation</span> privilégiée</li><li><span class=\"kw-etio\">HTA</span> : peut causer ou aggraver l'épistaxis ; si persistante après traitement, avis spécialisé pour un <span class=\"kw-ttt\">traitement de fond antihypertenseur</span></li></ul>","suivi":"<p><strong>Tamponnement antérieur :</strong> mèches non résorbables retirées à <span class=\"kw-chiffre\">24-48h</span> après correction des facteurs favorisants<br><strong>Sonde à double ballonnet :</strong> laissée au maximum <span class=\"kw-chiffre\">≤ 72h</span> ; <span class=\"kw-ttt\">dégonfler les ballonnets toutes les <span class=\"kw-chiffre\">6-8h</span></span> (risque de <span class=\"kw-alerte\">nécrose muqueuse</span>), dégonflage progressif dès <span class=\"kw-chiffre\">24-48h</span> ; surveiller l'<span class=\"kw-alerte\">escarre narinaire</span><br><strong>Bilan étiologique :</strong> lors de la PEC initiale ou dans <span class=\"kw-clinique\">les</span> jours suivants — <span class=\"kw-ttt\">examen endoscopique des cavités nasales</span> au minimum<br><strong>Prévention des récidives :</strong> <span class=\"kw-ttt\">cautérisation chimique ou électrique</span> de la tache vasculaire, <span class=\"kw-ttt\">idéalement à distance d'un épisode</span>, sous anesthésie locale en consultation ORL<br><strong><span class=\"kw-etio\">HTA</span> / coagulopathie :</strong> avis spécialisé si HTA persistante ; revoir l'indication des antithrombotiques</p>"},"liensGlobaux":[{"href":"https://radiopaedia.org/articles/epistaxis","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/nose","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/juvenile-nasopharyngeal-angiofibroma","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/hereditary-haemorrhagic-telangiectasia","label":"radiopaedia.org"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Épistaxis active confirmée — Écoulement sanglant des cavités nasales — premiers gestes : <span class=\"kw-ttt\">mouchage</span>, <span class=\"kw-ttt\">compression bidigitale antérieure 10 min</span>, position assise penchée en avant","detail":"<h4>CAT — Épistaxis — Triage de gravité puis escalade hémostatique en escalier</h4>","branches":[{"to":"q-gravite","label":"Évaluation initiale","color":"blue"}]},{"id":"q-gravite","kind":"decision","label":"Signes de gravité ou terrain à risque ? — Bilatéralité / saignement postérieur, abondance, retentissement hémodynamique, terrain polyvasculaire ou coronarien, trouble de la coagulation ou AVK, Rendu-Osler, tumeur","branches":[{"to":"t-grave","label":"Oui — épistaxis grave","color":"red"},{"to":"q-arret","label":"Non — épistaxis bénigne","color":"green"}]},{"id":"t-grave","kind":"terminal","label":"Épistaxis grave → hospitalisation en urgence","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Hospitalisation</span> en <span class=\"kw-alerte\">urgence</span>, voie veineuse, monitoring hémodynamique</li><li>Escalade hémostatique d'emblée en milieu <span class=\"kw-ttt\">ORL</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">bilan d'hémostase</span>, <span class=\"kw-bio\">groupe ABO-Rhésus-RAI</span> (bilan pré-transfusionnel), <span class=\"kw-bio\">créatininémie</span> si embolisation envisagée</li><li><span class=\"kw-imagerie\">Angio-TDM cervicofaciale</span> si post-traumatique avec suspicion de <span class=\"kw-clinique\">lésion</span> de la carotide interne ; <span class=\"kw-imagerie\">TDM du massif facial injectée</span> si suspicion de tumeur</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Transfusion de CGR</span> si <span class=\"kw-chiffre\">Hb < 7 g/dL</span> (<span class=\"kw-chiffre\">< 10 g/L si insuffisance coronarienne aiguë</span>)</li><li><span class=\"kw-ttt\">Transfusion de plaquettes</span> si choc hémorragique avec <span class=\"kw-chiffre\">plaquettes < 50 G/L</span></li></ul>"},{"id":"q-arret","kind":"decision","label":"Arrêt du saignement après compression 10 min ? — Épistaxis a priori bénigne, antérieure, siège de la tache de Kiesselbach","branches":[{"to":"t-benin","label":"Oui — arrêt","color":"green"},{"to":"t-escalade","label":"Non — persistance","color":"red"}]},{"id":"t-benin","kind":"terminal","label":"Épistaxis bénigne contrôlée → ambulatoire","color":"green","detail":"<h4>Conduite</h4><ul><li>Retour à domicile, <span class=\"kw-ttt\">aucun examen complémentaire</span> nécessaire en l'absence de gravité</li><li>Saignement de la <span class=\"kw-etio\">tache de Kiesselbach</span> : <span class=\"kw-ci\">pas de tamponnement</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Prévention des récidives : <span class=\"kw-ttt\">cautérisation</span> de la tache vasculaire, <span class=\"kw-ttt\">à distance d'un épisode</span>, sous anesthésie locale en consultation ORL</li></ul>"},{"id":"t-escalade","kind":"terminal","label":"Saignement persistant → escalade hémostatique — On ne passe à l'étape suivante qu'en cas d'échec ou de récidive","color":"red","detail":"<h4>Conduite</h4><ul><li>1. <span class=\"kw-ttt\">Méchage Xylocaïne-naphazoline</span><span class=\"kw-chiffre\"> 10 min</span> puis <span class=\"kw-ttt\">coagulation à la pince</span> si zone accessible</li><li>2. <span class=\"kw-ttt\">Tamponnement antérieur</span> si échec / récidive / saignement non visualisé</li><li>3. <span class=\"kw-ttt\">Tamponnement antéropostérieur</span> par <span class=\"kw-ttt\">sonde à double ballonnet</span> (saignement postérieur) — geste ORL</li><li>4. <span class=\"kw-ttt\">Ligature de l'artère sphénopalatine</span> ou <span class=\"kw-ttt\">embolisation des branches de la carotide externe</span> (privilégiée si <span class=\"kw-alerte\">trouble de l'hémostase</span>)</li><li>5. Dernier recours : <span class=\"kw-ttt\">ligature de l'artère ethmoïdale antérieure</span></li></ul><h4><span class=\"kw-ci\">Contre-indication</span></h4><ul><li><span class=\"kw-ci\">Jamais d'embolisation des artères ethmoïdales</span> : risque d'<span class=\"kw-alerte\">hémiplégie</span> ou de <span class=\"kw-alerte\">cécité</span></li></ul>"}]},"cards":[{"i":"021921562ce5","n":87,"o":"87-1","u":"Définition","t":"Connaître la définition d’une épistaxis","q":"Quelles sont les caractéristiques d'une épistaxis-maladie ou essentielle du sujet jeune ?","a":"<p>Il s'agit d'une épistaxis due à des <strong>ectasies</strong> de la <strong>tache vasculaire</strong> située à la partie antéro-inférieure de la cloison nasale, également appelée <strong>plexus de Kiesselbach</strong>.</p>"},{"i":"43917346700a","n":87,"o":"87-1","u":"Définition","t":"Connaître la définition d’une épistaxis","q":"Quelle est la définition générale d'une épistaxis ?","a":"<p>L'épistaxis désigne un <strong>écoulement sanglant</strong> provenant des <strong>cavités nasales</strong>.</p>"},{"i":"59e6e92e0bd1","n":87,"o":"87-1","u":"Définition","t":"Connaître la définition d’une épistaxis","q":"Quels sont les deux territoires anatomiques de saignement à distinguer lors d'une épistaxis ?","a":"<ul><li>L'<strong>épistaxis antérieure</strong>, la plus fréquente, est issue de la <strong>tache de Kiesselbach</strong> et est généralement accessible à l'examen.</li><li>L'<strong>épistaxis postérieure</strong>, provenant de l'<strong>artère sphénopalatine</strong>, est plus profonde et plus volontiers abondante.</li></ul>"},{"i":"fa8f853588c0","n":87,"o":"87-1","u":"Définition","t":"Connaître la définition d’une épistaxis","q":"Quelles sont des causes fréquentes d'épistaxis-symptôme ?","a":"<ul><li><strong>HTA</strong> (Hypertension Artérielle)</li><li><strong>Troubles de l'hémostase</strong></li><li><strong>Tumeurs nasosinusiennes</strong></li><li><strong>Maladie de Rendu-Osler</strong></li><li><strong>Traumatismes</strong></li></ul>"},{"i":"5f53c86df1c2","n":87,"o":"87-2","u":"Diagnostic positif","t":"Connaître les critères diagnostiques et de diagnostic différentiel","q":"Quelle est la présentation clinique d'une épistaxis postérieure ?","a":"<p>L'épistaxis postérieure se caractérise par un <strong>écoulement sanglant sur la paroi pharyngée postérieure</strong>, visible à l'examen pharyngé. Elle correspond à une extériorisation par les choanes et est généralement <strong>plus difficile à contrôler</strong>.</p>"},{"i":"64596faa58a3","n":87,"o":"87-2","u":"Diagnostic positif","t":"Connaître les critères diagnostiques et de diagnostic différentiel","q":"Comment est établi le diagnostic positif d'une épistaxis ?","a":"<p>Le diagnostic positif de l'épistaxis est essentiellement <strong>clinique</strong>, reposant sur l'observation d'un <strong>écoulement sanglant extériorisé</strong> par les narines ou par les choanes, confirmé par l'examen ORL après évacuation des caillots.</p>"},{"i":"71ce9bd14068","n":87,"o":"87-2","u":"Diagnostic positif","t":"Connaître les critères diagnostiques et de diagnostic différentiel","q":"Comment différencier une épistaxis d'une hématémèse ?","a":"<p>Une épistaxis est un saignement nasal, alors qu'une hématémèse est un saignement extériorisé principalement par la <strong>bouche</strong>, lors d'un effort de <strong>vomissement</strong>, et dont le sang est souvent <strong>digéré</strong> (type « marc de café ») avec éventuellement des résidus alimentaires.</p>"},{"i":"b9637050e257","n":87,"o":"87-2","u":"Diagnostic positif","t":"Connaître les critères diagnostiques et de diagnostic différentiel","q":"Comment différencier une épistaxis d'une hémoptysie ?","a":"<p>Une épistaxis est un saignement nasal, tandis qu'une hémoptysie est un <strong>saignement d'origine bronchique</strong>, extériorisé lors d'un effort de <strong>toux</strong>, et caractérisé par du <strong>sang rouge spumeux</strong>.</p>"},{"i":"c0d8bc765002","n":87,"o":"87-2","u":"Diagnostic positif","t":"Connaître les critères diagnostiques et de diagnostic différentiel","q":"Comment doit être préparé le patient avant l'examen ORL pour une épistaxis ?","a":"<ul><li><strong>Évacuation des caillots</strong> par mouchage.</li><li><strong>Méchage</strong> avec <strong>Xylocaïne à la naphazoline</strong> pendant <strong>10 minutes</strong> afin d'obtenir une anesthésie locale et une vasoconstriction.</li></ul>"},{"i":"ef63eb117903","n":87,"o":"87-2","u":"Diagnostic positif","t":"Connaître les critères diagnostiques et de diagnostic différentiel","q":"Quelle est la présentation clinique d'une épistaxis antérieure ?","a":"<p>L'épistaxis antérieure se manifeste par un <strong>écoulement sanglant extériorisé par les narines</strong>. Elle est la forme la plus fréquente, souvent <strong>unilatérale</strong>, et accessible à la <strong>rhinoscopie antérieure</strong>.</p>"},{"i":"f3b89a09f5ab","n":87,"o":"87-2","u":"Diagnostic positif","t":"Connaître les critères diagnostiques et de diagnostic différentiel","q":"Dans quel contexte évoquer une rupture carotidienne en diagnostic différentiel d'une épistaxis et quelle est sa gravité ?","a":"<p>Une rupture carotidienne doit être évoquée face à un saignement d'origine pharyngée chez un patient ayant des <strong>antécédents d'irradiation cervicofaciale</strong>. Il s'agit d'une <strong>urgence vitale absolue</strong>.</p>"},{"i":"01d10e7aa7b4","n":87,"o":"87-3","u":"Diagnostic positif","t":"Connaître les données d’interrogatoire et d’examen clinique à rechercher devant une épistaxis","q":"Quels éléments du terrain doivent être recherchés à l'interrogatoire devant une épistaxis ?","a":"<p>À l'interrogatoire, il faut rechercher les éléments de terrain suivants :</p><ul><li><strong>Âge élevé</strong>, insuffisance coronarienne, terrain polyvasculaire.</li><li><strong>Troubles de l'hémostase</strong> : constitutionnels ou acquis (<strong>AVK</strong>, <strong>AAPL</strong>, hémophilie, insuffisance hépatique).</li><li>Lésions nasales à risque hémorragique : <strong>Rendu-Osler</strong>, tumeur nasale ou sinusienne.</li><li><strong>HTA</strong>, <strong>traumatisme récent</strong>, prise de <strong>cocaïne</strong>.</li></ul>"},{"i":"058144a6673a","n":87,"o":"87-3","u":"Diagnostic positif","t":"Connaître les données d’interrogatoire et d’examen clinique à rechercher devant une épistaxis","q":"Quelles sont les caractéristiques d'une épistaxis bénigne et d'une épistaxis grave ?","a":"<ul><li>Une épistaxis est considérée comme <strong>bénigne</strong> si le saignement est <strong>antérieur unilatéral</strong>, <strong>goutte à goutte</strong>, souvent de la <strong>tache de Kiesselbach</strong>, et que l'<strong>état général est conservé</strong>.</li><li>Une épistaxis est considérée comme <strong>grave</strong> si le saignement est <strong>bilatéral antéro-postérieur</strong>, <strong>abondant</strong>, avec un <strong>retentissement hémodynamique</strong> (PA basse, pâleur, sueurs), ou s'il existe des co-morbidités à risque (coronaropathie, sténose carotidienne), et des troubles de la coagulation ou la prise d'<strong>AVK</strong>.</li></ul>"},{"i":"1dea5a8e2c93","n":87,"o":"87-3","u":"Diagnostic positif","t":"Connaître les données d’interrogatoire et d’examen clinique à rechercher devant une épistaxis","q":"Quels sont les objectifs de l'interrogatoire et de l'examen clinique devant une épistaxis ?","a":"<p>Devant une épistaxis, l'interrogatoire et l'examen clinique poursuivent trois objectifs simultanés :</p><ul><li>Évaluer la <strong>gravité</strong>.</li><li>Orienter l'<strong>étiologie</strong>.</li><li>Localiser le <strong>saignement</strong> pour guider le traitement.</li></ul>"},{"i":"a39fb3273514","n":87,"o":"87-3","u":"Diagnostic positif","t":"Connaître les données d’interrogatoire et d’examen clinique à rechercher devant une épistaxis","q":"Comment l'examen clinique permet-il d'orienter l'étiologie d'une épistaxis ?","a":"<p>L'examen clinique permet d'orienter l'étiologie d'une épistaxis de la manière suivante :</p><ul><li>L'examen facial recherche des <strong>télangiectasies</strong>, orientant vers une <strong>maladie de Rendu-Osler</strong>.</li><li>Un saignement <strong>unilatéral</strong> oriente généralement vers une cause <strong>locale</strong>.</li><li>Un saignement <strong>bilatéral</strong> oriente plutôt vers une cause <strong>générale</strong>.</li></ul>"},{"i":"d325c51e6da2","n":87,"o":"87-3","u":"Diagnostic positif","t":"Connaître les données d’interrogatoire et d’examen clinique à rechercher devant une épistaxis","q":"Quels sont les signes cliniques de gravité devant une épistaxis ?","a":"<p>Les signes cliniques de gravité devant une épistaxis incluent :</p><ul><li>Signes de choc : <strong>tachycardie</strong>, <strong>hypotension artérielle</strong>, <strong>pâleur</strong>, <strong>sueurs</strong>, <strong>agitation</strong>.</li><li>Puis, en cas d'aggravation : <strong>marbrures</strong>, <strong>cyanose</strong>, <strong>troubles de conscience</strong>.</li><li>Critères évocateurs d'un saignement abondant : <strong>bilatéralité</strong> du saignement, épistaxis antérieure <strong>ET</strong> postérieure, <strong>persistance</strong> depuis plusieurs jours.</li></ul>"},{"i":"1f5056084003","n":87,"o":"87-4","u":"Examens complémentaires","t":"Descrire les examens biologiques de base dans une épistaxis","q":"Dans quel contexte réalise-t-on des examens biologiques face à une épistaxis ?","a":"<p>La réalisation d'examens biologiques face à une épistaxis n'est <strong>pas systématique</strong>. Elle est indiquée uniquement en présence de <strong>signes de gravité</strong> ou selon le <strong>contexte étiologique</strong> de l'épistaxis.</p>"},{"i":"53003768ccfe","n":87,"o":"87-4","u":"Examens complémentaires","t":"Descrire les examens biologiques de base dans une épistaxis","q":"Quels examens biologiques de base sont indiqués en cas d'épistaxis avec signes de gravité ?","a":"<ul><li><strong>NFS</strong> (Numération Formule Sanguine) : pour évaluer l'hémoglobine (Hb) et les plaquettes.</li><li><strong>Bilan d'hémostase</strong> : TP (Taux de Prothrombine), TCA (Temps de Céphaline Activée), fibrinogène.</li><li><strong>Bilan pré-transfusionnel</strong> : groupe ABO, Rhésus, RAI (Recherche d'Agglutinines Irrégulières).</li><li><strong>Créatininémie</strong>.</li></ul>"},{"i":"a6bef8bc31aa","n":87,"o":"87-4","u":"Examens complémentaires","t":"Descrire les examens biologiques de base dans une épistaxis","q":"Quels examens biologiques spécifiques peuvent être envisagés lors d'une épistaxis selon le contexte étiologique ?","a":"<ul><li>Des <strong>études plus complètes de l'hémostase</strong> (temps de saignement, dosage des facteurs de la coagulation) si un trouble de la coagulation est suspecté.</li><li>Un <strong>ECG</strong> et la <strong>troponine</strong> si l'on recherche une souffrance myocardique.</li><li>La <strong>créatininémie</strong> si une artério-embolisation est envisagée, en particulier en prévision de l'utilisation d'un produit de contraste iodé.</li></ul>"},{"i":"4183ae302f77","n":87,"o":"87-7","u":"Prise en charge","t":"Connaître la stratégie thérapeutique dans une épistaxis","q":"Quelles sont les mesures générales et les premiers gestes à effectuer en cas d'épistaxis, y compris par le patient lui-même ?","a":"<p>Les mesures générales incluent :</p><ul><li>Position <strong>assise ou demi-assise</strong> (pour éviter l'inhalation).</li><li>Administration d'un <strong>anxiolytique</strong> si le patient est agité ou anxieux.</li><li>Les gestes que le patient peut effectuer comprennent : sucer un glaçon, évacuer les caillots par mouchage, positionner la tête surélevée et légèrement penchée en avant, et réaliser une <strong>compression bidigitale antérieure pendant 10 minutes 'montre en main'</strong>.</li><li>L'utilisation de tampons hémostatiques locaux à la partie antérieure de la fosse nasale est également possible par le patient.</li></ul>"},{"i":"981402c87334","n":87,"o":"87-7","u":"Prise en charge","t":"Connaître la stratégie thérapeutique dans une épistaxis","q":"Quelle est la séquence canonique de prise en charge médicale en cas d'échec des premiers gestes pour une épistaxis ?","a":"<p>En cas d'échec des premiers gestes, la séquence est la suivante :</p><ul><li><strong>Évacuation des caillots</strong> par mouchage.</li><li><strong>Méchage</strong> des cavités nasales avec des cotons imbibés de <strong>Xylocaïne à la naphazoline</strong> pendant plus de 10 minutes (anesthésie locale et vasoconstriction).</li><li>Examen des cavités nasales pour <strong>localiser le saignement</strong>.</li><li><strong>Hémostase élective par pince coagulante</strong> si la zone est accessible.</li><li>Si échec, récidive, ou site non visualisé : <strong>tamponnement antérieur</strong> classique.</li><li>Si échec du tamponnement antérieur (surtout si saignement postérieur) : <strong>tamponnement antéropostérieur</strong> par sonde à double ballonnet.</li></ul>"},{"i":"98f87e3cb58d","n":87,"o":"87-7","u":"Prise en charge","t":"Connaître la stratégie thérapeutique dans une épistaxis","q":"Comment évaluer la gravité initiale d'une épistaxis et qui hospitaliser ?","a":"<p>L'hospitalisation est indiquée pour les patients présentant des <strong>critères de gravité</strong> (notamment une insuffisance coronarienne) ou des difficultés de surveillance à domicile (âge, isolement, précarité). Il faut hospitaliser les patients qui nécessitent une <strong>transfusion</strong>, la pose d'une <strong>sonde à double ballonnet</strong>, ou tout autre geste hémostatique invasif.</p>"},{"i":"b742ccc34b8a","n":87,"o":"87-7","u":"Prise en charge","t":"Connaître la stratégie thérapeutique dans une épistaxis","q":"Quelles sont les options thérapeutiques après l'échec d'un tamponnement antéropostérieur pour une épistaxis ?","a":"<p>Après l'échec d'un tamponnement antéropostérieur, un <strong>avis spécialisé urgent</strong> est nécessaire pour envisager :</p><ul><li>La <strong>ligature</strong> ou l'<strong>embolisation</strong> de l'artère sphénopalatine (privilégier l'embolisation en cas de trouble de l'hémostase).</li><li>En dernier recours, la <strong>ligature de l'artère ethmoïdale antérieure</strong>.</li><li>Il est important de noter de ne <strong>jamais emboliser les artères ethmoïdales</strong> en raison du risque d'hémiplégie ou de cécité.</li></ul>"},{"i":"b905a5643ab9","n":87,"o":"87-7","u":"Prise en charge","t":"Connaître la stratégie thérapeutique dans une épistaxis","q":"Quelle est la prise en charge spécifique de l'épistaxis essentielle de la tache de Kiesselbach ?","a":"<p>Pour l'épistaxis essentielle de la tache de Kiesselbach, il ne faut <strong>pas réaliser de tamponnement</strong>. Le traitement repose sur la <strong>compression</strong> et éventuellement la <strong>cautérisation chimique ou électrique</strong>. L'idéal est de réaliser cette cautérisation à distance d'un épisode, sous anesthésie locale en consultation ORL.</p>"},{"i":"5fd1d8d78c03","n":87,"o":"87-9","u":"Étiologies","t":"Connaître les principales étiologies des épistaxis","q":"Comment classifie-t-on les épistaxis selon leur étiologie et quelle latéralité est généralement associée à chaque type ?","a":"<p>Les épistaxis se classifient en deux grands cadres :</p><ul><li><strong>Épistaxis d'origine locale</strong> : elles sont généralement <strong>unilatérales</strong>.</li><li><strong>Épistaxis d'origine générale</strong> : elles sont plutôt <strong>bilatérales</strong>.</li></ul>"},{"i":"695852bd65df","n":87,"o":"87-9","u":"Étiologies","t":"Connaître les principales étiologies des épistaxis","q":"Quels sont les mécanismes généraux pouvant causer ou aggraver une épistaxis ?","a":"<p>Les mécanismes généraux incluent :</p><ul><li>L'<strong>Hypertension Artérielle (HTA)</strong>, qui peut être une cause ou un facteur aggravant.</li><li>Les <strong>maladies hémorragiques</strong>, telles que :<ul><li>Les perturbations de l'hémostase primaire (capillarites, thrombopénies, thrombopathies comme celles induites par les <strong>antiagrégants</strong>, les <strong>AINS</strong>, la maladie de Glanzmann ou de <strong>Willebrand</strong>).</li><li>Les troubles de la coagulation (<strong>hémophilie</strong>, prise d'<strong>anticoagulants</strong>, insuffisance hépatique, CIVD).</li></ul></li></ul>"},{"i":"abe8c2bb2fad","n":87,"o":"87-9","u":"Étiologies","t":"Connaître les principales étiologies des épistaxis","q":"Qu'est-ce que l'épistaxis essentielle et quels sont les principaux facteurs favorisants ?","a":"<p>L'épistaxis essentielle est une <strong>épistaxis-maladie</strong> typique du sujet jeune, due à une ectasie de la <strong>tache vasculaire de Kiesselbach</strong>.</p><p>Les facteurs favorisants sont :</p><ul><li>Le grattage.</li><li>L'exposition solaire.</li><li>Les phénomènes vasomoteurs.</li><li>Les facteurs endocriniens (puberté, période prémenstruelle, grossesse).</li><li>L'artériosclérose (chez le sujet plus âgé).</li></ul>"},{"i":"f584f0a3e437","n":87,"o":"87-9","u":"Étiologies","t":"Connaître les principales étiologies des épistaxis","q":"Quelles sont les principales étiologies locales des épistaxis ?","a":"<p>Les principales étiologies locales d'épistaxis incluent :</p><ul><li>Les <strong>traumatismes</strong> (la cause la plus fréquente), incluant les corps étrangers (souvent chez l'enfant), les perforations septales, les traumatismes opératoires (intubation nasale, chirurgie naso-sinusienne) et les traumatismes crânio-faciaux (fracture des os propres du nez, fracture du tiers moyen de la face, traumatisme crânien avec atteinte des branches ethmoïdales ou rupture carotidienne dans le sinus sphénoïdal, pouvant entraîner une <strong>épistaxis foudroyante</strong>).</li></ul>"}]};